static Local<Value> createDOMException(Isolate* isolate, int errorCode, const char* message) {
  Local<Value> exception = v8::Null(isolate);
  switch (errorCode) {
    case 1:
      exception = Exception::Error(v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>(message)).ToLocalChecked());
      break;
    case 2:
      exception = Exception::TypeError(v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>(message)).ToLocalChecked());
      break;
    case 3:
      exception = Exception::RangeError(v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>(message)).ToLocalChecked());
      break;
    case 4:
      exception = Exception::SyntaxError(v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>(message)).ToLocalChecked());
      break;
    case 5:
      exception = Exception::ReferenceError(v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>(message)).ToLocalChecked());
      break;
    default:
      exception = Exception::Error(v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>(message)).ToLocalChecked());
      break;
  }

  // Attach stack trace to the exception for debugging purposes
  Local<Context> context = Context::New(isolate);
  Local<String> stackMessage = v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>(message)).ToLocalChecked();
  Local<Object> exceptionObject = exception.As<Object>();
  exceptionObject->Set(context, v8::String::NewFromOneByte(isolate, reinterpret_cast<const uint8_t*>("stack")).ToLocalChecked(), stackMessage).Check();

  return exception;
}

