// Function to create a DOM exception based on the error code
v8::Local<v8::Value> createDOMException(v8::Local<v8::Context> context, int errorCode, const char* message) {
    assert(!v8::Isolate::GetCurrent()->IsExecutionTerminating());

    v8::Local<v8::Object> exception;
    switch (errorCode) {
        case 1: // General error
            exception = v8::Exception::Error(v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)message));
            break;
        case 2: // Type error
            exception = v8::Exception::TypeError(v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)message));
            break;
        case 3: // Range error
            exception = v8::Exception::RangeError(v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)message));
            break;
        case 4: // Syntax error
            exception = v8::Exception::SyntaxError(v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)message));
            break;
        case 5: // Reference error
            exception = v8::Exception::ReferenceError(v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)message));
            break;
        default:
            exception = v8::Exception::Error(v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)"Unknown error"));
            break;
    }

    // Attach a stack trace
    v8::Local<v8::StackTrace> stack_trace = v8::StackTrace::CurrentStackTrace(v8::Isolate::GetCurrent(), 20);
    exception->Set(context, v8::String::NewFromOneByte(v8::Isolate::GetCurrent(), (const uint8_t*)"stack"), stack_trace).Check();

    return exception;
}

// Function to throw an exception in the V8 isolate
void throwException(v8::Local<v8::Context> context, int errorCode, const char* message) {
    v8::Isolate* isolate = v8::Isolate::GetCurrent();
    if (isolate->IsExecutionTerminating()) {
        return;
    }

    v8::Local<v8::Value> exception = createDOMException(context, errorCode, message);
    isolate->ThrowException(exception);
}

